macro_rules! is_dot_ntfs {
    () => {
        # [doc = " The `search_case_insensitive` name is the actual name to look for (in a case-insensitive way)."] # [doc = " Opposed to that there is the special `ntfs_shortname_prefix` which is derived from `search_case_insensitive`"] # [doc = " but looks more like a hash, one that NTFS uses to disambiguate things, for when there is a lot of files"] # [doc = " with the same prefix."] fn is_dot_ntfs (input : & BStr , search_case_insensitive : & str , ntfs_shortname_prefix : & str) -> bool { if input . first () == Some (& b'.') { let end_pos = 1 + search_case_insensitive . len () ; if input . get (1 .. end_pos) . is_some_and (| input | input . eq_ignore_ascii_case (search_case_insensitive . as_bytes ())) { is_done_ntfs (input . get (end_pos ..)) } else { false } } else { let search_case_insensitive : & [u8] = search_case_insensitive . as_bytes () ; if search_case_insensitive . get (.. 6) . zip (input . get (.. 6)) . is_some_and (| (ntfs_prefix , first_6_of_input) | { first_6_of_input . eq_ignore_ascii_case (ntfs_prefix) && input . get (6) == Some (& b'~') && input . get (7) . is_some_and (| num | (b'1' ..= b'4') . contains (num)) }) { return is_done_ntfs (input . get (8 ..)) ; } let ntfs_shortname_prefix : & [u8] = ntfs_shortname_prefix . as_bytes () ; let mut saw_tilde = false ; let mut pos = 0 ; while pos < 8 { let Some (b) = input . get (pos) . copied () else { return false ; } ; if saw_tilde { if ! b . is_ascii_digit () { return false ; } } else if b == b'~' { saw_tilde = true ; pos += 1 ; let Some (b) = input . get (pos) . copied () else { return false ; } ; if ! (b'1' ..= b'9') . contains (& b) { return false ; } } else if pos >= 6 || b & 0x80 == 0x80 || ntfs_shortname_prefix . get (pos) . is_none_or (| ob | ! b . eq_ignore_ascii_case (ob)) { return false ; } pos += 1 ; } is_done_ntfs (input . get (pos ..)) } }
    };
}

is_dot_ntfs!()